givenCode.code:
public static String checkVerdict(String got, int key) {
    String[] all = { "תקין", "שגיאת הידור", "שגיאת ריצה" };
    String g = got == null ? "null" : got.trim();
    if (g.equals(all[key % 3])) {
        return "נכון";
    }
    if (!g.equals(all[0]) && !g.equals(all[1]) && !g.equals(all[2])) {
        return "לא נכון — התקבל " + g + " (התשובה היא תקין, שגיאת הידור או שגיאת ריצה)";
    }
    return "לא נכון — התקבל " + g;
}

exercise.mainCode:
Animal a = new Dog("Rexy", 0.5, 3);
Mammal m = new Mammal("Numa", 2.5);
Object obj = m;
System.out.println("סעיף א, בדיקה 1: " + checkVerdict(answerA(), 31));
System.out.println("סעיף ב, בדיקה 1: " + checkVerdict(answerB(), 45));
System.out.println("סעיף ג, בדיקה 1: " + checkVerdict(answerC(), 53));
System.out.println("סעיף ד, בדיקה 1: " + checkVerdict(answerD(), 22));
System.out.println("סעיף ה, בדיקה 1: " + checkVerdict(answerE(), 64));
System.out.println("סעיף ו, בדיקה 1: " + checkVerdict(answerF(), 38));
System.out.println("סעיף ז, בדיקה 1: " + checkVerdict(answerG(), 57));

